enum DateTime64 {
    Nat,
    Valid(i64),
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Specification:
    // - Requires no preconditions (can take any Vec<DateTime64>)
    // - Ensures that the returned Vec<bool> has the same length as x,
    //   and each boolean indicates whether the corresponding element of x is DateTime64::Nat.
    //
    // Using Verus specs, we express this as:
    //
    // requires true;
    // ensures result.len() == x.len();
    // ensures forall|i: usize| i < x.len() ==> result[i] == (matches!(x[i], DateTime64::Nat));

    x.into_iter()
     .map(|dt| matches!(dt, DateTime64::Nat))
     .collect()
}